#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────


# Mise en ligne de l'étape i-web de J3 (#159) : vérifications locales (facultatives, sur un rattrapage local jamais
# poussé), fusion de la PR #160 et publication du site, nouveau déclencheur du cron du dépôt de données, rattrapage
# ciblé d'i-web en production, puis suivi du premier passage et de l'interface. Rien n'est poussé, fusionné, lancé ni
# commenté sans un « y » à la question.
#
#   scripts/mise-en-ligne-j3-i-web.sh         toutes les étapes, depuis la première
#   scripts/mise-en-ligne-j3-i-web.sh 7       reprendre à l'étape 7 (vérifications locales déjà faites, voir #159)
#   scripts/mise-en-ligne-j3-i-web.sh liste   la liste des étapes
#
# Variables : DONNEES (clone du dépôt de données, par défaut à côté de ce dépôt), TRAVAIL (journaux, listes à relire
# et notes de la relecture, hors des deux dépôts).

ETAPES=(
  "prealables|Préalables : branche j3/i-web, outils, PR #160, retrait durable"
  "clone|Clone du dépôt de données à côté du dépôt"
  "rattrapage|Facultatif : rattrapage local des communes i-web, jamais poussé (environ 3 h 30)"
  "comptes|Facultatif : Séances et Objets de chaque commune contre son site"
  "masquage|Facultatif : titres masqués et communes sans page des membres"
  "second_import|Facultatif : passage ordinaire, durée, requêtes, rien de neuf ; clone remis à zéro"
  "fusion|Fusionner la PR #160 et publier le site"
  "declencheur|Nouveau déclencheur du cron du dépôt de données"
  "rattrapage_prod|Rattrapage ciblé d'i-web en production (environ 3 h 30)"
  "suivi|Sondes, imports et issues du dépôt de données"
  "interface|Vérifier l'interface en ligne, sur bureau et sur téléphone"
  "fil|Remesurer le volume du fil et le consigner dans #144"
  "bilan|Bilan et commentaire sur #159"
)
TOTAL_STAGES=${#ETAPES[@]}

DEPOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
PIPELINE="$DEPOT/pipeline"
DONNEES="${DONNEES:-$(dirname "$DEPOT")/vigie-vaud-donnees}"
TRAVAIL="${TRAVAIL:-${XDG_STATE_HOME:-$HOME/.local/state}/vigie-vaud/mise-en-ligne-j3-i-web}"
NOTES="$TRAVAIL/notes.md"
ENV_FILE="$TRAVAIL/valeurs.env"   # `ask` y cherche ses valeurs par défaut ; rien n'y est écrit
BRANCHE=j3/i-web
PR=160
TICKET=159
SPEC=144
RETRAIT=141
REPO_CODE=Louni-M/vigie-vaud
REPO_DONNEES=Louni-M/vigie-vaud-donnees
SITE=https://louni-m.github.io/vigie-vaud
PAGES_DONNEES=https://louni-m.github.io/vigie-vaud-donnees
mkdir -p "$TRAVAIL"

# ── Outils des étapes ─────────────────────────────────────────────────────

# lancer CMD… affiche la commande, puis la lance.
lancer() { printf '  %s$ %s%s\n' "$DIM" "$*" "$RESET"; "$@"; }
# gd ARGS… : git dans le clone du dépôt de données.
gd() { git -C "$DONNEES" "$@"; }
# py ARGS… <<'PY' : Python du pipeline (modules du cron), lancé depuis `pipeline/`.
py() { (cd "$PIPELINE" && uv run --quiet python - "$@"); }
# voir FICHIER : une longue liste à relire, dans le pager.
voir() { if [[ -t 1 ]]; then less -R -F -X "$1"; else cat "$1"; fi; }
arreter() { printf '\n'; warn "$1"; note "Reprendre avec : scripts/mise-en-ligne-j3-i-web.sh $_STAGE_INDEX"; exit 1; }
noter() { printf -- '- %s · %s\n' "$(date '+%F %R')" "$1" >> "$NOTES"; }
# valider "question" : y, ou bien une remarque notée pour la suite.
valider() {
  if confirm "$1"; then
    noter "OK · $1"
  else
    ask REMARQUE "Ce qui ne va pas (noté dans $NOTES) :"
    noter "À REPRENDRE · $1 · ${REMARQUE:-sans précision}"
    warn "noté ; à reprendre avant d'aller plus loin si c'est bloquant"
  fi
}
suite() { printf '\n'; pause "Entrée : étape suivante"; }
ok() { printf '  %s✓ %s%s\n' "$GREEN" "$1" "$RESET"; }
# depot_propre : le clone du dépôt de données n'a aucun changement en cours.
depot_propre() { [[ -z "$(gd status --porcelain)" ]]; }
# lancer_long FICHIER_JOURNAL CMD… : une commande longue, machine tenue éveillée, journal gardé.
lancer_long() {
  local journal="$1"; shift
  local cafe=()
  command -v caffeinate >/dev/null 2>&1 && cafe=(caffeinate -ims)
  note "Journal : $journal"
  printf '  %s$ %s%s\n' "$DIM" "$*" "$RESET"
  local debut=$SECONDS
  if ! (cd "$PIPELINE" && PYTHONUNBUFFERED=1 ${cafe[@]+"${cafe[@]}"} "$@") 2>&1 | tee "$journal"; then
    arreter "la commande a échoué : voir $journal"
  fi
  printf '%s\n' $(((SECONDS - debut) / 60)) > "$journal.minutes"
  printf '\n  %s✓ terminé en %d min%s\n' "$GREEN" $(((SECONDS - debut) / 60)) "$RESET"
}
# echecs_du_journal FICHIER : les imports en échec et les pannes affichés par le passage.
echecs_du_journal() {
  if grep -E "^(Import en échec|Panne|Import sauté)" "$1"; then
    warn "le passage a signalé des échecs (ci-dessus)"
    return 1
  fi
  ok "aucun import en échec, aucune panne"
}
# cron_actif : le workflow du cron du dépôt de données est activé.
cron_actif() { [[ "$(gh workflow view cron.yml -R "$REPO_DONNEES" --json state -q .state 2>/dev/null)" == "active" ]]; }

# ── 1 ─────────────────────────────────────────────────────────────────────
etape_prealables() {
  say "Le rattrapage tourne avec le code de l'étape i-web : il faut la branche $BRANCHE, à jour et propre."
  local manque=0 outil
  for outil in git gh uv curl python3 less; do
    command -v "$outil" >/dev/null 2>&1 || { warn "$outil introuvable"; manque=1; }
  done
  (( manque == 0 )) || arreter "installer les outils manquants"
  gh auth status >/dev/null 2>&1 || arreter "gh n'est pas connecté : gh auth login"
  command -v caffeinate >/dev/null 2>&1 || warn "caffeinate absent : empêcher la mise en veille à la main pendant le rattrapage"

  local branche; branche=$(git -C "$DEPOT" rev-parse --abbrev-ref HEAD)
  [[ "$branche" == "$BRANCHE" ]] || arreter "le dépôt est sur $branche : git switch $BRANCHE"
  lancer git -C "$DEPOT" fetch --quiet origin
  if [[ -n "$(git -C "$DEPOT" status --porcelain --untracked-files=no)" ]]; then
    warn "changements en cours dans $DEPOT (le rattrapage tournera avec eux) :"
    git -C "$DEPOT" status --short --untracked-files=no
  fi
  if [[ "$(git -C "$DEPOT" rev-parse HEAD)" != "$(git -C "$DEPOT" rev-parse "origin/$BRANCHE")" ]]; then
    warn "$BRANCHE diffère de origin/$BRANCHE (git pull) :"
    git -C "$DEPOT" log --oneline --left-right "HEAD...origin/$BRANCHE" | head -n 10
  else
    ok "$BRANCHE à jour ($(git -C "$DEPOT" log -1 --format=%h))"
  fi

  say ""
  say "PR #$PR :"
  gh pr view "$PR" -R "$REPO_CODE" --json state,mergeStateStatus,title \
    -q '"  \(.state) · \(.mergeStateStatus) · \(.title[0:70])…"'
  gh pr checks "$PR" -R "$REPO_CODE" 2>/dev/null | sed 's/^/  /' || true

  say ""
  say "Prérequis de la spec : le retrait durable (#$RETRAIT) est dans main."
  if [[ "$(gh issue view "$RETRAIT" -R "$REPO_CODE" --json state -q .state)" == "CLOSED" ]] \
    && git -C "$DEPOT" cat-file -e "origin/main:pipeline/retraits.py" 2>/dev/null; then
    ok "#$RETRAIT fermé, pipeline/retraits.py dans main"
  else
    arreter "#$RETRAIT n'est pas fusionné dans main : aucune commune scrapée ne se publie avant lui"
  fi
  git -C "$DEPOT" merge-base --is-ancestor origin/main HEAD \
    && ok "$BRANCHE contient main" \
    || warn "$BRANCHE ne contient pas tout main : git merge origin/main avant le rattrapage"

  say ""
  if gh api "repos/$REPO_DONNEES/contents/conseils/5643/seances" >/dev/null 2>&1; then
    note "conseils/5643 (Préverenges) existe déjà sur $REPO_DONNEES : le cron lit déjà les sites i-web"
  else
    ok "aucune commune i-web encore importée sur $REPO_DONNEES"
  fi

  say ""
  lancer uv sync --quiet --project "$PIPELINE"
  note "Notes de la relecture : $NOTES"
  suite
}

# ── 2 ─────────────────────────────────────────────────────────────────────
etape_clone() {
  say "Le rattrapage s'écrit dans un clone du dépôt de données : $DONNEES"
  if [[ -d "$DONNEES/.git" ]]; then
    ok "clone présent"
    gd remote get-url origin | grep -q "vigie-vaud-donnees" || arreter "$DONNEES n'est pas un clone de $REPO_DONNEES"
    [[ "$(gd rev-parse --abbrev-ref HEAD)" == "main" ]] || arreter "le clone n'est pas sur main"
    depot_propre || { gd status --short; arreter "le clone a des changements en cours"; }
    lancer gd fetch --quiet origin
    if [[ -n "$(gd log --oneline origin/main..HEAD)" ]]; then
      warn "commits locaux non poussés (un rattrapage déjà fait ?) :"
      gd log --oneline origin/main..HEAD | head -n 10
      note "Un rattrapage local d'une séance précédente ? Le garder pour les étapes 4 à 6, ou le défaire :"
      note "git -C $DONNEES reset --hard origin/main"
    else
      lancer gd pull --ff-only --quiet
    fi
  else
    lancer git clone "https://github.com/$REPO_DONNEES.git" "$DONNEES"
  fi
  say ""
  gd log -3 --format='  %h %s'
  suite
}

# ── 3 ─────────────────────────────────────────────────────────────────────
etape_rattrapage() {
  say "Le passage du cron avec --rattrapage-cible i-web et sans push : la sonde de chaque commune i-web couverte,"
  say "puis tout son site, sans plafond, une requête à la fois et au moins 5 s par réseau. Les 19 communes sont"
  say "sur le même réseau i-web : compter environ 3 h 30 (3 h 28 le 23 octobre). Puis un commit dans le clone,"
  say "jamais poussé : la production refait son propre rattrapage à l'étape 9. Déjà fait le 23 octobre"
  say "(chiffres dans #159) : passer les étapes 3 à 6 avec scripts/mise-en-ligne-j3-i-web.sh 7, sauf pour revérifier."
  step "Laisser ce terminal ouvert et la machine branchée (caffeinate la garde éveillée)."
  step "Si la session coupe : refaire cette étape (scripts/mise-en-ligne-j3-i-web.sh 3) ; rien n'est poussé."
  say ""
  [[ "$(git -C "$DEPOT" rev-parse --abbrev-ref HEAD)" == "$BRANCHE" ]] || arreter "le dépôt n'est plus sur $BRANCHE"
  depot_propre || { gd status --short | head; arreter "le clone a des changements en cours"; }
  if ! confirm "Lancer le rattrapage maintenant ?"; then
    warn "rattrapage non lancé ; les vérifications suivantes en ont besoin"
    suite; return
  fi
  gd rev-parse HEAD > "$TRAVAIL/avant-rattrapage"
  lancer_long "$TRAVAIL/rattrapage.log" uv run python cron.py --depot "$DONNEES" --sans-push --rattrapage-cible i-web
  say ""
  echecs_du_journal "$TRAVAIL/rattrapage.log" || true
  grep -E " : [0-9]+ Objet\(s\), [0-9]+ Séance\(s\) lus" "$TRAVAIL/rattrapage.log" | sed 's/^/  /' || true
  grep -E "^Retrait sans effet|élément sauté" "$TRAVAIL/rattrapage.log" | sed 's/^/  /' || true
  say ""
  gd log -1 --format='  Commit %h « %s »'
  gd show --stat --format= HEAD | tail -n 1 | sed 's/^/ /'
  noter "Rattrapage local i-web : $(gd log -1 --format='%h %s'), $(cat "$TRAVAIL/rattrapage.log.minutes") min, journal $TRAVAIL/rattrapage.log"
  suite
}

# ── 4 ─────────────────────────────────────────────────────────────────────
etape_comptes() {
  say "Séances et Objets de chaque commune i-web dans l'archive, avec la plus ancienne et la plus récente Séance."
  py "$DONNEES" "$TRAVAIL/comptes.txt" <<'PY'
import sys
from pathlib import Path
from schema import RACINE, lire_sources

depot, sortie = Path(sys.argv[1]), Path(sys.argv[2])
ligne = "  {:<28} {:<22} {:>8} {:>7}  {:<10}  {:<10}  {}"
lignes = [ligne.format("commune", "donne", "Séances", "Objets", "première", "dernière", "page des Séances")]
for s in lire_sources(RACINE / "sources.json").sources:
    if not s.site or s.site.plateforme != "i-web" or s.conseil is None:
        continue
    dossier = depot / "conseils" / s.conseil.cle
    jours = sorted(f.stem[:10] for f in (dossier / "seances").glob("*.json"))
    objets = len(list((dossier / "objets").glob("*.json")))
    lignes.append(ligne.format(s.nom_court.removeprefix("Site de ").removeprefix("Site d'"), "+".join(s.conseil.donne),
                               len(jours), objets, jours[0] if jours else "—", jours[-1] if jours else "—",
                               s.site.seances or ""))
sortie.write_text("\n".join(lignes) + "\n", encoding="utf-8")
PY
  voir "$TRAVAIL/comptes.txt"
  say ""
  say "Comparer au moins trois communes à leur site (une par variante : Préverenges, Puidoux, Blonay - Saint-Légier) :"
  step "le nombre de Séances en ligne sur la page des Séances, et la plus ancienne ;"
  step "pour Puidoux, le nombre de préavis."
  if confirm "Ouvrir les pages des Séances de Préverenges, Puidoux et Blonay - Saint-Légier ?"; then
    local url
    for url in $(py <<'PY'
from schema import RACINE, lire_sources
for s in lire_sources(RACINE / "sources.json").sources:
    if s.id in ("site-5643", "site-5607", "site-5892"):
        print(s.site.seances)
PY
    ); do open_url "$url"; done
  fi
  valider "Séances et Objets de l'archive conformes aux sites comparés ?"
  noter "Comptes par commune : $TRAVAIL/comptes.txt"
  suite
}

# ── 5 ─────────────────────────────────────────────────────────────────────
etape_masquage() {
  say "Tous les titres masqués des communes i-web, puis tous les titres de Faoug et de Bottens, qui n'ont pas de"
  say "page des membres (leurs élu·e·s nommé·e·s après une civilité sont donc masqué·e·s par défaut)."
  py "$DONNEES" "$TRAVAIL/masquage.txt" <<'PY'
import json, re, sys
from pathlib import Path
from schema import RACINE, lire_sources

depot, sortie = Path(sys.argv[1]), Path(sys.argv[2])
SANS_MEMBRES = {"5458", "5514"}  # Faoug, Bottens
CIVILITE = re.compile(r"\b(M\.|Mme|Mmes|MM\.|Monsieur|Madame)\s")

def textes(element):
    yield element.get("titre") or element.get("nom") or ""
    for p in element.get("ordre_du_jour", []):
        yield p.get("titre") or ""
    for d in element.get("documents", []):
        yield d.get("titre") or ""

masques, civilites, tous = [], [], []
for s in lire_sources(RACINE / "sources.json").sources:
    if not s.site or s.site.plateforme != "i-web" or s.conseil is None:
        continue
    cle = s.conseil.cle
    for f in sorted((depot / "conseils" / cle).glob("*/*.json")):
        if f.parent.name not in ("objets", "seances"):
            continue
        for t in textes(json.loads(f.read_text(encoding="utf-8"))):
            ligne = f"{cle}/{f.stem}  {t}"
            if "[particulier]" in t or "[coordonnées]" in t:
                masques.append(ligne)
            elif CIVILITE.search(t):
                civilites.append(ligne)
            if cle in SANS_MEMBRES:
                tous.append(ligne)

parties = [
    (f"Titres masqués ({len(masques)}) : le masque tombe-t-il sur un particulier, et lui seul ?", masques),
    (f"Civilités restées lisibles ({len(civilites)}) : chacune doit être un·e élu·e connu·e", civilites),
    (f"Tous les titres de Faoug et Bottens ({len(tous)}) : aucun particulier lisible", tous),
]
sortie.write_text("\n\n".join(t + "\n" + "\n".join("  " + l for l in ls) for t, ls in parties) + "\n", encoding="utf-8")
PY
  voir "$TRAVAIL/masquage.txt"
  say ""
  note "Un nom de particulier encore lisible : le noter ici, puis l'ajouter à retraits.json (docs/retrait.md) ou"
  note "corriger le masquage avant de pousser."
  valider "Aucun particulier lisible, aucun·e élu·e connu·e masqué·e à tort ?"
  noter "Titres relus : $TRAVAIL/masquage.txt"
  suite
}

# ── 6 ─────────────────────────────────────────────────────────────────────
etape_second_import() {
  say "Un passage ordinaire des 19 communes juste après le rattrapage, comme le cron le fera chaque jour : fenêtre"
  say "de 6 mois, plafond de 60 requêtes par commune. On relève sa durée, le nombre de requêtes de chaque commune,"
  say "et qu'il ne change rien à l'archive (un import qui réécrit tout chaque jour remplirait l'historique)."
  depot_propre || { gd status --short | head; arreter "le clone a des changements en cours"; }
  if ! confirm "Lancer le passage ordinaire maintenant (une dizaine de minutes) ?"; then
    warn "passage non lancé"; suite; return
  fi
  local debut=$SECONDS
  py "$DONNEES" "$TRAVAIL/requetes.txt" <<'PY' 2>&1 | tee "$TRAVAIL/second-import.log"
import sys
from collections import Counter
from datetime import UTC, datetime
from pathlib import Path
import httpx
from conseils import OpenParlData, importer_conseils
from robot_communal import robot_des_sources
from schema import RACINE, lire_sources

depot, sortie = Path(sys.argv[1]), Path(sys.argv[2])
sources = lire_sources(RACINE / "sources.json")
sites = {s.conseil.cle for s in sources.sources if s.site and s.site.plateforme == "i-web" and s.conseil}
hotes = Counter()
horloge = lambda: datetime.now(UTC)  # noqa: E731
with httpx.Client(event_hooks={"request": [lambda r: hotes.update([r.url.host])]}) as http:
    robot = robot_des_sources(http, sources, horloge)  # passage ordinaire : plafond de 60 requêtes par commune
    importer_conseils(depot, sources, OpenParlData(http, horloge), horloge, dus=sites, robot=robot)
lignes = [f"  {n:>3}  {h}" for h, n in hotes.most_common()]
sortie.write_text("\n".join(lignes) + "\n", encoding="utf-8")
print(f"Requêtes : {sum(hotes.values())} au total, {max(hotes.values(), default=0)} au plus pour un site")
PY
  local minutes=$(((SECONDS - debut) / 60))
  say ""
  sed 's/^/  /' "$TRAVAIL/requetes.txt" | head -n 25
  say ""
  echecs_du_journal "$TRAVAIL/second-import.log" || true
  local changes; changes=$(gd status --porcelain -- conseils | grep -v "conseils/import.json" || true)
  if [[ -z "$changes" ]]; then
    ok "rien de neuf dans l'archive ni dans les fichiers de lecture (seul conseils/import.json change)"
  else
    warn "le passage ordinaire a changé des fichiers :"
    printf '%s\n' "$changes" | head -n 20 | sed 's/^/  /'
  fi
  noter "Passage ordinaire : $minutes min, $(tail -n 1 "$TRAVAIL/second-import.log")"
  valider "Passage ordinaire sans changement, sous le plafond, en une durée raisonnable ($minutes min) ?"
  say ""
  say "Le rattrapage local a servi : le clone revient à origin/main (rien n'est poussé)."
  lancer gd fetch --quiet origin
  lancer gd reset --quiet --hard origin/main
  lancer gd clean -fdq
  suite
}

# ── 9 ─────────────────────────────────────────────────────────────────────
etape_fusion() {
  say "La PR #$PR fusionnée dans main, puis la publication du site (workflow « publier », lancé à la main) : $SITE"
  gh pr view "$PR" -R "$REPO_CODE" --json state,mergeStateStatus -q '"  \(.state) · \(.mergeStateStatus)"'
  if [[ "$(gh pr view "$PR" -R "$REPO_CODE" --json state -q .state)" == "OPEN" ]]; then
    if confirm "Fusionner la PR #$PR (commit de fusion) ?"; then
      lancer gh pr merge "$PR" -R "$REPO_CODE" --merge
    else
      arreter "PR non fusionnée"
    fi
  else
    ok "PR #$PR déjà fusionnée"
  fi
  say ""
  if ! confirm "Lancer la publication du site maintenant ?"; then
    warn "site non publié"; noter "Publication non lancée"; suite; return
  fi
  local avant id="" i
  avant=$(gh run list -R "$REPO_CODE" --workflow publier.yml -L 1 --json databaseId -q '.[0].databaseId // ""')
  lancer gh workflow run publier.yml -R "$REPO_CODE" --ref main
  for i in {1..30}; do
    id=$(gh run list -R "$REPO_CODE" --workflow publier.yml -L 1 --json databaseId -q '.[0].databaseId // ""')
    [[ -n "$id" && "$id" != "$avant" ]] && break
    id=""; sleep 2
  done
  [[ -n "$id" ]] || arreter "le passage de la publication n'apparaît pas : https://github.com/$REPO_CODE/actions"
  gh run watch "$id" -R "$REPO_CODE" --exit-status \
    || arreter "la publication a échoué : gh run view $id -R $REPO_CODE --log-failed"
  noter "PR #$PR fusionnée, site publié : passage $id"
  suite
}

# ── 8 ─────────────────────────────────────────────────────────────────────
etape_declencheur() {
  say "Le déclencheur du cron, dans le dépôt de données, gagne l'entrée rattrapage_cible et les délais de job. Il"
  say "n'est poussé qu'après la fusion : avant, le workflow réutilisable de main ne connaissait pas cette entrée."
  [[ "$(gh pr view "$PR" -R "$REPO_CODE" --json state -q .state)" == "MERGED" ]] || arreter "PR #$PR non fusionnée : étape 7"
  depot_propre || { gd status --short | head; arreter "le clone a des changements en cours"; }
  lancer gd fetch --quiet origin
  [[ -z "$(gd log --oneline origin/main..HEAD)" ]] || arreter "le clone a des commits locaux : git -C $DONNEES reset --hard origin/main"
  lancer gd merge --ff-only --quiet origin/main
  # Le modèle est celui de main, quelle que soit la branche du dépôt.
  local modele="$TRAVAIL/cron.yml" cible="$DONNEES/.github/workflows/cron.yml"
  git -C "$DEPOT" fetch --quiet origin
  git -C "$DEPOT" show "origin/main:pipeline/depot-donnees/.github/workflows/cron.yml" > "$modele"
  if cmp -s "$modele" "$cible"; then
    ok "déclencheur déjà à jour"
  else
    diff -u "$cible" "$modele" | sed 's/^/  /' | head -n 40 || true
    if confirm "Recopier ce déclencheur (celui de main) dans le dépôt de données et le pousser ?"; then
      lancer cp "$modele" "$cible"
      lancer gd add .github/workflows/cron.yml
      lancer gd commit --quiet -m "Déclencheur du cron de l'étape i-web de J3 : rattrapage ciblé et délais"
      if ! gd push --quiet origin main; then
        # Un passage du cron a committé entre-temps : on rejoue le commit du déclencheur par-dessus.
        lancer gd pull --rebase --quiet origin main
        lancer gd push --quiet origin main
      fi
      noter "Déclencheur poussé : $(gd log -1 --format=%h)"
    else
      arreter "déclencheur non poussé : le rattrapage ciblé ne peut pas être lancé sans lui"
    fi
  fi
  suite
}

# ── 9 ─────────────────────────────────────────────────────────────────────
etape_rattrapage_prod() {
  say "Le rattrapage ciblé d'i-web, lancé à la main sur le cron du dépôt de données : tout le site de chaque commune"
  say "i-web couverte, sans plafond, au même débit, puis commit, push et publication des Pages des données. Les"
  say "passages planifiés attendent sa fin (même groupe de concurrence). Compter environ 3 h 30, sous le délai de"
  say "6 h du job."
  cron_actif || arreter "le cron de $REPO_DONNEES est désactivé : gh workflow enable cron.yml -R $REPO_DONNEES"
  gh run list -R "$REPO_DONNEES" --workflow cron.yml --limit 3 \
    --json status,conclusion,createdAt,event -q '.[] | "  \(.createdAt) · \(.event) · \(.status) \(.conclusion // "")"'
  if ! confirm "Lancer le rattrapage ciblé d'i-web en production ?"; then
    warn "rattrapage non lancé"; suite; return
  fi
  local avant id="" i
  avant=$(gh run list -R "$REPO_DONNEES" --workflow cron.yml -L 1 --event workflow_dispatch --json databaseId -q '.[0].databaseId // ""')
  lancer gh workflow run cron.yml -R "$REPO_DONNEES" -f rattrapage_cible=i-web
  for i in {1..30}; do
    id=$(gh run list -R "$REPO_DONNEES" --workflow cron.yml -L 1 --event workflow_dispatch --json databaseId -q '.[0].databaseId // ""')
    [[ -n "$id" && "$id" != "$avant" ]] && break
    id=""; sleep 2
  done
  [[ -n "$id" ]] || arreter "le rattrapage n'apparaît pas : https://github.com/$REPO_DONNEES/actions"
  note "Suivi : https://github.com/$REPO_DONNEES/actions/runs/$id (Ctrl-C n'arrête que ce suivi, pas le rattrapage)"
  local cafe=(); command -v caffeinate >/dev/null 2>&1 && cafe=(caffeinate -ims)
  ${cafe[@]+"${cafe[@]}"} gh run watch "$id" -R "$REPO_DONNEES" --exit-status --interval 60 \
    || arreter "le rattrapage a échoué : gh run view $id -R $REPO_DONNEES --log-failed"
  gh run view "$id" -R "$REPO_DONNEES" --log 2>/dev/null \
    | grep -E "Objet\(s\), [0-9]+ Séance\(s\) lus|Import en échec|Import sauté|Retrait sans effet" \
    | sed -E 's/^[^\t]*\t[^\t]*\t[^ ]+ //; s/^/  /' > "$TRAVAIL/rattrapage-prod.txt" || true
  cat "$TRAVAIL/rattrapage-prod.txt"
  noter "Rattrapage ciblé i-web en production : passage $id"
  suite
}

