# ── 12 ────────────────────────────────────────────────────────────────────
etape_fil() {
  say "Volume que les communes i-web ajoutent au fil cantonal : Séances et préavis par quinzaine, sur un an, d'après"
  say "le dépôt de données après le rattrapage de production."
  depot_propre || { gd status --short | head; arreter "le clone a des changements en cours"; }
  lancer gd pull --ff-only --quiet origin main
  py "$DONNEES" "$TRAVAIL/fil.txt" <<'PY'
import json, sys
from datetime import date, timedelta
from pathlib import Path
from schema import RACINE, lire_sources

depot, sortie = Path(sys.argv[1]), Path(sys.argv[2])
fin = date.today()
debut = fin - timedelta(days=364)
seances, preavis = [], []
for s in lire_sources(RACINE / "sources.json").sources:
    if not s.site or s.site.plateforme != "i-web" or s.conseil is None:
        continue
    dossier = depot / "conseils" / s.conseil.cle
    seances += [date.fromisoformat(f.stem[:10]) for f in (dossier / "seances").glob("*.json")]
    for f in (dossier / "objets").glob("*.json"):
        o = json.loads(f.read_text(encoding="utf-8"))
        if o.get("depose"):
            preavis.append(date.fromisoformat(o["depose"]))

def par_quinzaine(jours):
    comptes = [0] * 26
    for j in jours:
        if debut <= j <= fin:
            comptes[min((j - debut).days // 14, 25)] += 1
    return comptes

lignes = []
for nom, jours in (("Séances", seances), ("Objets (préavis)", preavis)):
    c = par_quinzaine(jours)
    lignes.append(f"{nom} : {sum(c)} sur un an, {sum(c) / 26:.1f} par quinzaine en moyenne, {max(c)} au plus")
sortie.write_text(f"Communes i-web, du {debut} au {fin}\n" + "\n".join(lignes) + "\n", encoding="utf-8")
PY
  sed 's/^/  /' "$TRAVAIL/fil.txt"
  noter "Volume du fil : $(tr '\n' ' ' < "$TRAVAIL/fil.txt")"
  if confirm "Consigner ce volume en commentaire sur #$SPEC ?"; then
    { printf 'Volume du fil après la mise en ligne de l'"'"'étape i-web (#%s) :\n\n' "$TICKET"; sed 's/^/- /' "$TRAVAIL/fil.txt"; } \
      > "$TRAVAIL/fil-commentaire.md"
